-- V0000__sys_baseline：若依 sys_*/gen_*（20 表）+ qrtz_*（11 表）PG 化 DDL 与种子，源自 sql/ry_20260417.sql + sql/quartz.sql
-- 注：简报按 19 表计；pristine 3.9.2 基线实含 sys_notice_read（Java 代码在用），故 sys/gen 为 20 表、合计 31 表
-- 方言转换规则：反引号删除；InnoDB 表尾子句整段删除；类型去宽度（bigint(20)→bigint、int(11)→int、tinyint(1)→smallint）；
--   datetime→timestamp；longblob→text（种子为纯文本、Java 映射 String）；blob→bytea；自增列→generated by default as identity；
--   表内 key/unique key 外提为 create index；列/表 comment 外提为 comment on；服务器时间函数统一 now()；反斜杠转义改写为标准 SQL 写法；
--   sys_job 种子 invoke_target 对齐任务 2 改名（ryTask.ry*→jknowTask.jknow*）；种子后 setval 对齐原 MySQL 自增起始计数。

-- ============================================================
-- 第一部分：sys_*/gen_* 表 DDL（20 张，源自 sql/ry_20260417.sql，保持原文件顺序）
-- ============================================================

-- ----------------------------
-- 1、部门表
-- ----------------------------
drop table if exists sys_dept;
create table sys_dept (
  dept_id           bigint          generated by default as identity,
  parent_id         bigint          default 0,
  ancestors         varchar(50)     default '',
  dept_name         varchar(30)     default '',
  order_num         int             default 0,
  leader            varchar(20)     default null,
  phone             varchar(11)     default null,
  email             varchar(50)     default null,
  status            char(1)         default '0',
  del_flag          char(1)         default '0',
  create_by         varchar(64)     default '',
  create_time       timestamp,
  update_by         varchar(64)     default '',
  update_time       timestamp,
  primary key (dept_id)
);
comment on table sys_dept is '部门表';
comment on column sys_dept.dept_id is '部门id';
comment on column sys_dept.parent_id is '父部门id';
comment on column sys_dept.ancestors is '祖级列表';
comment on column sys_dept.dept_name is '部门名称';
comment on column sys_dept.order_num is '显示顺序';
comment on column sys_dept.leader is '负责人';
comment on column sys_dept.phone is '联系电话';
comment on column sys_dept.email is '邮箱';
comment on column sys_dept.status is '部门状态（0正常 1停用）';
comment on column sys_dept.del_flag is '删除标志（0代表存在 2代表删除）';
comment on column sys_dept.create_by is '创建者';
comment on column sys_dept.create_time is '创建时间';
comment on column sys_dept.update_by is '更新者';
comment on column sys_dept.update_time is '更新时间';

