    is_nonconcurrent     varchar(1)      null,
    requests_recovery    varchar(1)      null,
    primary key (sched_name, entry_id)
);
comment on table QRTZ_FIRED_TRIGGERS is '已触发的触发器表';
comment on column QRTZ_FIRED_TRIGGERS.sched_name is '调度名称';
