-- ============================================================
-- 第三部分：种子数据（全部 insert，保持 sql/ry_20260417.sql 原文件顺序；时间函数统一 now()，sys_job invoke_target 对齐任务 2 的 jknowTask 改名）
-- ============================================================

-- ----------------------------
