insert into sys_notice values('3', '若依开源框架介绍', '1', '<p><span style="color: rgb(230, 0, 0);">项目介绍</span></p><p><font color="#333333">RuoYi开源项目是为企业用户定制的后台脚手架框架，为企业打造的一站式解决方案，降低企业开发成本，提升开发效率。主要包括用户管理、角色管理、部门管理、菜单管理、参数管理、字典管理、</font><span style="color: rgb(51, 51, 51);">岗位管理</span><span style="color: rgb(51, 51, 51);">、定时任务</span><span style="color: rgb(51, 51, 51);">、</span><span style="color: rgb(51, 51, 51);">服务监控、登录日志、操作日志、代码生成等功能。其中，还支持多数据源、数据权限、国际化、Redis缓存、Docker部署、滑动验证码、第三方认证登录、分布式事务、</span><font color="#333333">分布式文件存储</font><span style="color: rgb(51, 51, 51);">、分库分表处理等技术特点。</span></p><p><img src="https://foruda.gitee.com/images/1773931848342439032/a4d22313_1815095.png" style="width: 64px;"><br></p><p><span style="color: rgb(230, 0, 0);">官网及演示</span></p><p><span style="color: rgb(51, 51, 51);">若依官网地址：&nbsp;</span><a href="http://ruoyi.vip" target="_blank">http://ruoyi.vip</a><a href="http://ruoyi.vip" target="_blank"></a></p><p><span style="color: rgb(51, 51, 51);">若依文档地址：&nbsp;</span><a href="http://doc.ruoyi.vip" target="_blank">http://doc.ruoyi.vip</a><br></p><p><span style="color: rgb(51, 51, 51);">演示地址【不分离版】：&nbsp;</span><a href="http://demo.ruoyi.vip" target="_blank">http://demo.ruoyi.vip</a></p><p><span style="color: rgb(51, 51, 51);">演示地址【分离版本】：&nbsp;</span><a href="http://vue.ruoyi.vip" target="_blank">http://vue.ruoyi.vip</a></p><p><span style="color: rgb(51, 51, 51);">演示地址【微服务版】：&nbsp;</span><a href="http://cloud.ruoyi.vip" target="_blank">http://cloud.ruoyi.vip</a></p><p><span style="color: rgb(51, 51, 51);">演示地址【移动端版】：&nbsp;</span><a href="http://h5.ruoyi.vip" target="_blank">http://h5.ruoyi.vip</a></p><p><br style="color: rgb(48, 49, 51); font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 12px;"></p>', '0', 'admin', now(), '', null, '管理员');

-- ============================================================
-- 第四部分：identity 序列对齐原 MySQL 自增计数（setval 第三参 false → 下一生成值恰为 N）
-- 有种子的表取 max(原表尾自增值, 种子最大ID+1)；sys_post 无表选项，取种子最大 4+1=5；
-- sys_job_log / sys_notice_read / gen_table / gen_table_column 原计数为 1 且无种子，identity 默认起点即 1，无需 setval
-- ============================================================
select setval(pg_get_serial_sequence('sys_dept',       'dept_id'),    200,  false);
select setval(pg_get_serial_sequence('sys_user',        'user_id'),    100,  false);
select setval(pg_get_serial_sequence('sys_post',        'post_id'),    5,    false);
select setval(pg_get_serial_sequence('sys_role',        'role_id'),    100,  false);
select setval(pg_get_serial_sequence('sys_menu',        'menu_id'),    2000, false);
select setval(pg_get_serial_sequence('sys_oper_log',    'oper_id'),    100,  false);
select setval(pg_get_serial_sequence('sys_dict_type',   'dict_id'),    100,  false);
select setval(pg_get_serial_sequence('sys_dict_data',   'dict_code'),  100,  false);
select setval(pg_get_serial_sequence('sys_config',      'config_id'),  100,  false);
select setval(pg_get_serial_sequence('sys_logininfor',  'info_id'),    100,  false);
select setval(pg_get_serial_sequence('sys_job',         'job_id'),     100,  false);
select setval(pg_get_serial_sequence('sys_notice',      'notice_id'),  10,   false);

commit;
